package com.spidy.servlet;import com.spidy.util.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/view-questions") public class ViewQuestionsServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse p)throws IOException,ServletException{if(!Auth.admin(r)){p.sendRedirect("admin-login.jsp");return;}try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("SELECT id,title,category,difficulty,xp_reward FROM missions ORDER BY id DESC")){r.setAttribute("questions",s.executeQuery());r.getRequestDispatcher("view-questions.jsp").forward(r,p);}catch(Exception e){r.getSession().setAttribute("msg",e.getMessage());p.sendRedirect("admin-dashboard.jsp");}}}
